class MajorityChecker {
  private final int[] tree;
  private final java.util.Map<Integer, java.util.List<Integer>> positions =
      new java.util.HashMap<>();
  private final int n;

  public MajorityChecker(int[] arr) {
    n = arr.length;
    tree = new int[4 * n];
    for (int i = 0; i < n; i++)
      positions.computeIfAbsent(arr[i], k -> new java.util.ArrayList<>()).add(i);
    build(arr, 1, 0, n - 1);
  }

  private void build(int[] a, int node, int lo, int hi) {
    if (lo == hi) {
      tree[node] = a[lo];
      return;
    }
    int mid = (lo + hi) >>> 1;
    build(a, node * 2, lo, mid);
    build(a, node * 2 + 1, mid + 1, hi);
    tree[node] = tree[node * 2] == tree[node * 2 + 1] ? tree[node * 2] : 0;
  }

  private int[] queryCandidate(int node, int lo, int hi, int left, int right) {
    if (left <= lo && hi <= right) return new int[] {tree[node], tree[node] == 0 ? 0 : 1};
    int mid = (lo + hi) >>> 1;
    if (right <= mid) return queryCandidate(node * 2, lo, mid, left, right);
    if (left > mid) return queryCandidate(node * 2 + 1, mid + 1, hi, left, right);
    int[] a = queryCandidate(node * 2, lo, mid, left, right),
        b = queryCandidate(node * 2 + 1, mid + 1, hi, left, right);
    if (a[0] == b[0]) return new int[] {a[0], a[1] + b[1]};
    if (a[1] > b[1]) return new int[] {a[0], a[1] - b[1]};
    return new int[] {b[0], b[1] - a[1]};
  }

  public int query(int left, int right, int threshold) {
    int candidate = queryCandidate(1, 0, n - 1, left, right)[0];
    if (candidate == 0) return -1;
    java.util.List<Integer> list = positions.get(candidate);
    int count = upperBound(list, right) - lowerBound(list, left);
    return count >= threshold ? candidate : -1;
  }

  private int lowerBound(java.util.List<Integer> a, int x) {
    int l = 0, r = a.size();
    while (l < r) {
      int m = (l + r) >>> 1;
      if (a.get(m) < x) l = m + 1;
      else r = m;
    }
    return l;
  }

  private int upperBound(java.util.List<Integer> a, int x) {
    int l = 0, r = a.size();
    while (l < r) {
      int m = (l + r) >>> 1;
      if (a.get(m) <= x) l = m + 1;
      else r = m;
    }
    return l;
  }
}
